Here's a Go program that calculates the first `n` prime numbers efficiently, using the Sieve of Eratosthenes algorithm. It takes the command line parameter `n` to determine how many prime numbers to find.

```go
package main

import (
	"fmt"
	"os"
	"strconv"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run main.go <n>")
		return
	}

	n, err := strconv.Atoi(os.Args[1])
	if err != nil || n <= 0 {
		fmt.Println("Please provide a valid positive integer for n.")
		return
	}

	primes := sieveOfEratosthenes(n)
	for _, prime := range primes {
		fmt.Println(prime)
	}
}

// sieveOfEratosthenes generates a slice of the first n prime numbers.
func sieveOfEratosthenes(n int) []int {
	limit := estimateUpperBound(n)
	isPrime := make([]bool, limit+1)
	for i := 2; i <= limit; i++ {
		isPrime[i] = true
	}

	for p := 2; p*p <= limit; p++ {
		if isPrime[p] {
			for i := p * p; i <= limit; i += p {
				isPrime[i] = false
			}
		}
	}

	var primes []int
	for p := 2; len(primes) < n && p <= limit; p++ {
		if isPrime[p] {
			primes = append(primes, p)
		}
	}

	return primes
}

// estimateUpperBound returns a rough upper bound for the nth prime number.
func estimateUpperBound(n int) int {
	if n < 6 {
		return 15
	}
	return int(float64(n) * (1.5 * float64(n) / 2)) // Using n log n approximation
}
```

