```csharp
using UnityEngine;
using System.Net.Sockets;
using System.Text;

public class SimpleTCPClient : MonoBehaviour
{
    private TcpClient client;
    private NetworkStream stream;

    void Start()
    {
        Connect("127.0.0.1", 8080);
        SendMessage("Hello Server");
        ReceiveMessage();
        Disconnect();
    }

    void Connect(string ip, int port)
    {
        client = new TcpClient(ip, port);
        stream = client.GetStream();
    }

    void SendMessage(string message)
    {
        byte[] data = Encoding.ASCII.GetBytes(message);
        stream.Write(data, 0, data.Length);
    }

    void ReceiveMessage()
    {
        byte[] buffer = new byte[1024];
        int bytesRead = stream.Read(buffer, 0, buffer.Length);
        string response = Encoding.ASCII.GetString(buffer, 0, bytesRead);
        Debug.Log("Received: " + response);
    }

    void Disconnect()
    {
        stream.Close();
        client.Close();
    }
}
```

This implementation connects to a TCP server, sends a message, receives a response, and then disconnects, all while keeping the code minimal and straightforward. You can modify the IP address and port to fit your server configuration.

