The Stoer-Wagner algorithm is a famous algorithm used for finding the minimum cut of an undirected, weighted graph. Here's a sample implementation in Swift.

First, ensure that you have a basic understanding of the algorithm and that you've set up a project where you can run Swift code.

Below is a simple implementation of the Stoer-Wagner algorithm:

```swift
import Foundation

class Graph {
    var vertices: [String]
    var adjacencyMatrix: [[Int]]

    init(vertices: [String]) {
        self.vertices = vertices
        self.adjacencyMatrix = Array(repeating: Array(repeating: 0, count: vertices.count), count: vertices.count)
    }

    func addEdge(from source: Int, to destination: Int, weight: Int) {
        adjacencyMatrix[source][destination] = weight
        adjacencyMatrix[destination][source] = weight // because the graph is undirected
    }

    func minCut() -> (Int, [String], [String]) {
        var minCutValue = Int.max

        var verticesCopy = vertices
        var inA = Array(repeating: false, count: vertices.count)

        for _ in 0..<vertices.count - 1 {
            var lastAdded = -1
            var weights = Array(repeating: 0, count: vertices.count)
            var added = Array(repeating: false, count: vertices.count)

            for _ in 0..<verticesCopy.count {
                var maxWeight = -1
                for j in 0..<verticesCopy.count {
                    if !added[j] && weights[j] > maxWeight {
                        maxWeight = weights[j]
                        lastAdded = j
                    }
                }

                if lastAdded == -1 {
                    break
                }

                added[lastAdded] = true
                inA[lastAdded] = true

                for j in 0..<verticesCopy.count {
                    if !added[j] {
                        weights[j] += adjacencyMatrix[lastAdded][j]
                    }
                }
            }

            // Last added vertex is `lastAdded`
            let s = lastAdded
            // `t` is the remaining vertex
            let t = verticesCopy.enumerated().first { !$0.element.isEqual(to: inA) }!.offset

            minCutValue = min(minCutValue, weights[s])

            if minCutValue == weights[s] {
                let A = verticesCopy.enumerated().filter { inA[$0.offset] }.map { $0.element }
                let B = verticesCopy.enumerated().filter { !$0.element.isEqual(to: inA) }.map { $0.element }
                return (minCutValue, A, B)
            }

            // Merge the two sets
            for i in 0..<verticesCopy.count {
                // Add weights to the new vertex, merge `s` and `t`
                if i != t {
                    adjacencyMatrix[s][i] += adjacencyMatrix[t][i]
                    adjacencyMatrix[i][s] += adjacencyMatrix[i][t]
                }
            }

            // Remove vertex `t` from the graph
            verticesCopy.remove(at: t)
            for i in 0..<adjacencyMatrix.count {
                adjacencyMatrix[i].remove(at: t)
            }
            adjacencyMatrix.remove(at: t)
        }

        return (minCutValue, [], [])
    }
}

// Usage
let vertices = ["A", "B", "C", "D"]
let graph = Graph(vertices: vertices)
graph.addEdge(from: 0, to: 1, weight: 1) // A-B
graph.addEdge(from: 0, to: 2, weight: 2) // A-C
graph.addEdge(from: 1, to: 2, weight: 2) // B-C
graph.addEdge(from: 1, to: 3, weight: 1) // B-D
graph.addEdge(from: 2, to: 3, weight: 2) // C-D

let (minCutValue, setA, setB) = graph.minCut()
print("Minimum cut value: \(minCutValue)")
print("Set A: \(setA)")
print("Set B: \(setB)")
```

### Explanation:
- **Graph Class**: This class encapsulates the graph's structure with methods to add edges and calculate the minimum cut.
- **Add Edge**: The `addEdge` method adds a weighted edge between two vertices.
- **minCut Method**: Implements the Stoer-Wagner algorithm to find the minimum cut value, returning it along with the two sets of vertices that form the cut.
- **Usage Example**: At the bottom of the code, I provided an example usage to create a graph and find its minimum cut.

Note: This implementation is primarily educational and might require optimizations or error handling for production-level code.

