func minCut(graph: [[Int]]) -> Int {
    var numVertices = graph.count
    var a: [Bool] = Array(repeating: false, count: numVertices)
    var bestCutSize = Int.max

    for _ in 0..<numVertices-1 {
        var v = -1
        var maxs = -1
        for i in 0..<numVertices {
            if !a[i] {
                let s = graph[i].reduce(0, +)
                if s > maxs {
                    maxs = s
                    v = i
                }
            }
        }

        a[v] = true

        var prev = v
        for _ in 0..<numVertices-1 {
            if !a[v] {
                a[v] = true
                for i in 0..<numVertices {
                    if !a[i] {
                        graph[prev][i] += graph[v][i]
                        graph[i][prev] += graph[v][i]
                    }
                }
                prev = v
            }

            v = -1
            maxs = -1
            for i in 0..<numVertices {
                if !a[i] {
                    let s = graph[i].reduce(0, +)
                    if s > maxs {
                        maxs = s
                        v = i
                    }
                }
            }
        }

        var cutSize = 0
        for i in 0..<numVertices {
            if !a[i] {
                cutSize += graph[i].reduce(0, +)
            }
        }

        bestCutSize = min(bestCutSize, cutSize)
    }

    return bestCutSize
}

// Example usage
let graph = [[0, 2, 0, 3],
             [2, 0, 2, 0],
             [0, 2, 0, 2],
             [3, 0, 2, 0]]

let minCutSize = minCut(graph: graph)
print("Minimum cut size: \(minCutSize)")
```

This implementation takes an adjacency matrix representation of a weighted undirected graph as input and returns the size of the minimum cut. The implementation follows the basic steps of the Stoer-Wagner algorithm as described in the algorithm's pseudocode.

