Certainly! The Stoer-Wagner algorithm is an efficient method for finding the minimum cut of an undirected weighted graph. Below is a sample implementation in Swift:

```swift
import Foundation

class StoerWagner {
    // Function to perform the Stoer-Wagner algorithm
    func minCut(weights: [[Int]]) -> (cutValue: Int, partitions: (Int, Int)) {
        let n = weights.count
        var bestCutValue = Int.max
        var bestPartitions = (0, 0)

        var vertices = Array(0..<n)

        while vertices.count > 1 {
            let (lastA, lastB) = findMinCutPhase(weights: &weights, vertices: &vertices)
            let cutValue = weights[lastA][lastB]

            if cutValue < bestCutValue {
                bestCutValue = cutValue
                bestPartitions = (vertices[lastA], vertices[lastB])
            }
            contractGraph(lastA: lastA, lastB: lastB, vertices: &vertices, weights: &weights)
        }

        return (bestCutValue, bestPartitions)
    }

    private func findMinCutPhase(weights: inout [[Int]], vertices: inout [Int]) -> (Int, Int) {
        let n = vertices.count
        var a = Array(repeating: false, count: n)
        var weight = Array(repeating: 0, count: n)

        var lastA = 0
        var lastB = 0

        for _ in 0..<n - 1 {
            var maxWeight = -1
            for i in 0..<n {
                if !a[i] {
                    weight[i] += (lastA == vertices[i]) ? 0 : weights[lastA][vertices[i]]
                    if weight[i] > maxWeight {
                        maxWeight = weight[i]
                        lastB = i
                    }
                }
            }
            a[lastB] = true
            lastA = lastB
        }

        return (lastA, lastB)
    }

    private func contractGraph(lastA: Int, lastB: Int, vertices: inout [Int], weights: inout [[Int]]) {
        let vertexA = vertices[lastA]
        let vertexB = vertices[lastB]

        for i in 0..<weights.count {
            if i != lastB && i != lastA {
                weights[vertexA][i] += weights[vertexB][i]
                weights[i][vertexA] += weights[i][vertexB]
            }
        }

        vertices.remove(at: lastB)
    }
}

// Sample usage
let weights = [
    [0, 10, 5, 0, 0],
    [10, 0, 2, 1, 0],
    [5, 2, 0, 0, 0],
    [0, 1, 0, 0, 2],
    [0, 0, 0, 2, 0],
]

let stoerWagner = StoerWagner()
let result = stoerWagner.minCut(weights: weights)
print("Minimum Cut Value: \(result.cutValue), Partitions: \(result.partitions)")
```

### Explanation:
- **Functionality**: The `minCut` function calculates the minimum cut using the Stoer-Wagner algorithm, leveraging a helper function to find the most tightly connected vertex and another for graph contraction.
- **Input**: The algorithm takes a 2D array `weights`, where `weights[i][j]` represents the weight of the edge between vertex `i` and vertex `j`.
- **Output**: It returns the minimum cut value and the two partitions that form the cut.

